import React, { useState } from 'react';
import './MenuForms.css';

const MenuForms = () => {
    const [info, setInfo] = useState('');

    const scrollToInfo = (newInfo) => {
        setInfo(newInfo);
        const infoSection = document.getElementById('info-section');
        if (infoSection) {
            infoSection.scrollIntoView({ behavior: 'smooth' });
        }
    };

    const infoData = {
        ahorro: "FinanTec te ayuda a establecer metas de ahorro realistas y a crear un presupuesto efectivo que se ajuste a tus necesidades.",
        jubilacion: "Planificar tu jubilación es esencial. Te proporcionamos herramientas para asegurarte un retiro cómodo y seguro.",
        metas: "Definir tus metas a corto y largo plazo te permitirá maximizar tu capacidad de ahorro y alcanzar tus sueños."
    };

    return (
        <div className="menu-form">
            <h2>¿En qué puede ayudarte FinanTec?</h2>
            <div className="menu-options">
                <div className="saving-box green" onClick={() => scrollToInfo(infoData.ahorro)}>
                    <div className="icon">💰</div>
                    <span>Generar Ahorro</span>
                </div>
                <div className="saving-box blue" onClick={() => scrollToInfo(infoData.jubilacion)}>
                    <div className="icon">🏦</div>
                    <span>Plan de Jubilación</span>
                </div>
                <div className="saving-box pink" onClick={() => scrollToInfo(infoData.metas)}>
                    <div className="icon">🎯</div>
                    <span>Metas Largo/Corto Plazo</span>
                </div>
            </div>

            {/* Sección de información */}
            <div id="info-section" className="info-section">
                <h3>Información sobre {info || 'FinanTec'}</h3>
                <p>
                    {info || 'FinanTec es tu aliado en el camino hacia una mejor salud financiera. Aquí te proporcionamos herramientas y recursos para ayudarte a:'}
                </p>
                <p>- Establecer metas de ahorro realistas.</p>
                <p>- Crear un presupuesto efectivo que se ajuste a tus necesidades.</p>
                <p>- Identificar y reducir gastos innecesarios para maximizar tu capacidad de ahorro.</p>
                <p>- Planificar tu futuro y asegurar un retiro confortable.</p>
                <p>¡Comienza hoy y transforma tu manera de gestionar tus finanzas!</p>
            </div>
        </div>
    );
};

export default MenuForms;
